        txt2 = str(ev.get("campotxt2") or "")
        txt4 = str(ev.get("campotxt4") or "")
        if txt2.startswith("resAso="):
            _p  = dict(x.split("=", 1) for x in txt2.split("/") if "=" in x)
            res = _p.get("resAso", "")
