@app.route("/cad_dep")
def cad_dep():
    if not session.get("logado"):
        return redirect("/")
    mats_raw = request.args.get("mats", "").strip()
    mats = [int(m) for m in mats_raw.split(",") if m.strip().isdigit()]
    if len(mats) != 1:
        return redirect("/select_funcionario?contexto=dep")
    matricula  = mats[0]
    id_empresa = _get_id_empresa()
    func_nome  = ""
    try:
        r = (supabase.table("tab_cad")
             .select("nome, nomer")
             .eq("id_empresa", id_empresa)
             .eq("matricula", matricula)
             .limit(1)
             .execute())
        if r.data:
            func_nome = (r.data[0].get("nomer") or r.data[0].get("nome") or "").strip()
    except Exception:
        pass
    tipos_dep = []
    try:
        r = (supabase.table("tab_tabela_total")
             .select("codigo, texto")
             .eq("num_tabela", 7)
             .neq("codigo", "DOC")
             .order("codigo")
             .execute())
        tipos_dep = r.data or []
    except Exception:
        pass
    return render_template(
        "F10_Cad_Dep.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        matricula=matricula,
        func_nome=func_nome,
        tipos_dep=tipos_dep,
    )


