@app.route("/api/esocial_s2206_buscar_func")
def api_esocial_s2206_buscar_func():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})
    id_empresa = _get_id_empresa()
    matricula  = request.args.get("matricula", "").strip()
    if not matricula:
        return jsonify({"ok": False, "msg": "Matrícula não informada."})
    try:
        r = (supabase.table("tab_cad").select("*")
             .eq("id_empresa", id_empresa)
             .eq("matricula", int(matricula)).limit(1).execute())
        if not r.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        return jsonify({"ok": True, "func": r.data[0]})
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})


# =========================================================
# eSocial S-2206 — API: gerar + assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s2206_enviar", methods=["POST"])
def api_esocial_s2206_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}

    id_reg = data.get("id_esocial")
    tpAmb  = str(data.get("tpAmb", "1")).strip()

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    # Lê o registro existente em tab_esocial
    try:
        r_es = (supabase.table("tab_esocial").select("*")
                .eq("id_esocial", id_reg).eq("id_empresa", id_empresa)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        reg_es    = r_es.data[0]
        matricula = reg_es.get("matricula")
        dc = str(reg_es.get("data_cad") or "")
        dt_alteracao = f"{dc[:4]}-{dc[4:6]}-{dc[6:8]}" if len(dc) == 8 else datetime.now().strftime("%Y-%m-%d")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    # Lê dados atuais do funcionário
    try:
        r_func = (supabase.table("tab_cad").select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", int(matricula)).limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)
    agora     = datetime.now()

    try:
        xml_str = _gerar_xml_s2206(func, empresa, dt_alteracao, tpAmb)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    import os as _os2
    _now2    = datetime.now()
    _dir_xml = _os2.path.join(_os2.path.dirname(__file__),
                               "eSocial_XML", _now2.strftime("%Y"),
                               _now2.strftime("%Y-%m"), str(id_empresa).zfill(6))
    _os2.makedirs(_dir_xml, exist_ok=True)
    _ts   = _now2.strftime("%Y%m%d_%H%M%S")
    _pref = _os2.path.join(_dir_xml, f"S2206_{matricula}_{_ts}")

    try:
        with open(f"{_pref}_1_evento.xml", "w", encoding="utf-8") as _f: _f.write(xml_str)
    except Exception: pass

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    try:
        with open(f"{_pref}_2_assinado.xml", "w", encoding="utf-8") as _f: _f.write(xml_assinado)
    except Exception: pass

    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str, grupo="2")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    try:
        with open(f"{_pref}_3_lote.xml", "w", encoding="utf-8") as _f: _f.write(lote_xml)
    except Exception: pass

    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        with open(f"{_pref}_4_soap_envio.xml", "w", encoding="utf-8") as _f: _f.write(soap_env)
    except Exception: pass

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        try:
            with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f: _f.write(detalhe)
        except Exception: pass
        supabase.table("tab_esocial").update({
            "data_grava": agora.strftime("%Y%m%d"),
            "hora_grava": agora.strftime("%H%M"),
            "observacao_erro": detalhe[:295],
        }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    try:
        with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f: _f.write(resp_envio)
    except Exception: pass

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]

    agora = datetime.now()
    if not protocolo_envio:
        supabase.table("tab_esocial").update({
            "data_grava": agora.strftime("%Y%m%d"),
            "hora_grava": agora.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.", "detalhe": analise["erro"]})

    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break
        try:
            with open(f"{_pref}_6_resultado_consulta.xml", "w", encoding="utf-8") as _f: _f.write(resp_cons)
        except Exception: pass
        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break
        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue
        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-2206 enviado: mat={matricula} nrRec={recibo_final} cd={cd_resp}",
               matricula=int(matricula))

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "id_esocial": id_reg,
        "msg": ("eSocial ainda processando. Use Re-consultar." if aguardando
                else obs_erro or f"Enviado com sucesso. Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-2206 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s2206_reconsultar", methods=["POST"])
def api_esocial_s2206_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("observacao_erro, matricula")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa).limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        obs = (r_es.data[0].get("observacao_erro") or "")
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está aguardando."})

    protocolo_envio = obs[len("AGUARDANDO:"):]

    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break
        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break
        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue
        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"[{cd_resp}] {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    ok = bool(recibo_final) and not obs_erro
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial — Fila Central de Remessas
# =========================================================
@app.route("/esocial_fila")
def esocial_fila():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")

    periodo  = request.args.get("periodo", anomes_atual).replace("-", "")[:6]
    f_layout = request.args.get("layout", "").strip()

    rows = []
    if periodo and len(periodo) == 6:
        try:
            # 1) registros cujo ano_mes bate com o período (exclui S-3000)
            q1 = (supabase.table("tab_esocial")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("ano_mes", int(periodo))
                  .neq("layout", "3000")
                  .order("data_cad", desc=True)
                  .order("hora_cad", desc=True))
            if f_layout:
                q1 = q1.eq("layout", f_layout)
            r1 = q1.execute().data or []

            # 2) registros sem ano_mes criados no mês do período (exclui S-3000)
            q2 = (supabase.table("tab_esocial")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .is_("ano_mes", "null")
                  .neq("layout", "3000")
                  .gte("data_cad", periodo + "01")
                  .lte("data_cad", periodo + "31")
                  .order("data_cad", desc=True)
                  .order("hora_cad", desc=True))
            if f_layout:
                q2 = q2.eq("layout", f_layout)
            r2 = q2.execute().data or []

            # mescla sem duplicatas, ordena por data/hora decrescente
            seen = set()
            for r in r1 + r2:
                if r["id_esocial"] not in seen:
                    seen.add(r["id_esocial"])
                    rows.append(r)
            rows.sort(key=lambda r: (r.get("data_cad", ""), r.get("hora_cad", "")), reverse=True)
        except Exception:
            pass

    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    _LAY = {
        "1000": ("S-1000", "Empregador",    "/esocial_s1000",    False),
        "1010": ("S-1010", "Rubricas",      "/esocial_s1010",    False),
        "1200": ("S-1200", "Remuneração",   "/esocial_s1200",    False),
        "1210": ("S-1210", "Pagamentos",    "/esocial_s1210",    False),
        "1298": ("S-1298", "Reabertura",    "/esocial_s1298",    False),
        "1299": ("S-1299", "Fechamento",    "/esocial_s1299",    False),
        "2200": ("S-2200", "Admissão",      "/esocial_s2200",    True),
        "2205": ("S-2205", "Alt.Cadastral", "/esocial_s2205",    True),
        "2206": ("S-2206", "Alt.Contrato",  "/esocial_s2206",    True),
        "2220": ("S-2220", "Saúde",         "/cad_exame_med",    True),
        "2230": ("S-2230", "Afastamento",   "/cad_afastamento",  True),
        "2299": ("S-2299", "Desligamento",  "#",                 True),
    }
    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    def _d8_fila(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    import json as _json_fila

    for r in rows:
        lay  = str(r.get("layout") or "")
        info = _LAY.get(lay, (f"S-{lay}", "", "#", False))
        r["_lay_codigo"]  = info[0]
        r["_lay_desc"]    = info[1]
        r["_lay_href"]    = info[2]
        r["_lay_func"]    = info[3]
        r["_nome"]        = nomes.get(r.get("matricula"), "—") if r.get("matricula") else "—"
        r["_datacad_fmt"] = _d8_fila(r.get("data_cad"))
        r["_verba_cod"]   = ""
        r["_verba_dsc"]   = ""
        if lay == "1010":
            obs_f = (r.get("observacao_erro") or "").strip()
            p_raw = obs_f.split("|")[0] if "|" in obs_f else obs_f
            if p_raw.startswith("PARAMS:"):
                try:
                    pj = _json_fila.loads(p_raw[7:])
                    cod = pj.get("cod_rubr")
                    if cod is not None:
                        r["_verba_cod"] = str(int(cod)).zfill(4)
                        r["_verba_dsc"] = pj.get("dsc_rubr", "")
                except Exception:
                    pass

        _hg = str(r.get("hora_grava") or "").strip()
        _dg = str(r.get("data_grava") or "").strip()
        if len(_dg) == 8 and len(_hg) >= 4:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]} {_hg[0:2]}:{_hg[2:4]}"
        elif len(_dg) == 8:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]}"
        else:
            r["_envio_fmt"] = ""

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]
        r["_operacao"]  = str(r.get("operacao") or "I").upper()

        am = r.get("ano_mes")
        if am:
            am_s = str(am)
            r["_periodo_fmt"] = f"{am_s[4:6]}/{am_s[0:4]}" if len(am_s) == 6 else str(am)
        else:
            r["_periodo_fmt"] = ""

    return render_template(
        "F10_eSocial_Fila.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows,
        total=len(rows),
        anomes_atual=anomes_atual,
        periodo=periodo,
        f_layout=f_layout,
    )


# =========================================================
# eSocial — Fila de Remessas — PDF
# =========================================================
@app.route("/rel_esocial_fila_pdf")
def rel_esocial_fila_pdf():
    if not session.get("logado"):
        return redirect("/")

    from io import BytesIO

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")
    empresa_nm   = str(session.get("empresa_info") or "")
    cnpj_fmt     = _fmt_cnpj(session.get("cnpj_empresa", ""))

    periodo  = request.args.get("periodo", anomes_atual).replace("-", "")[:6]
    f_layout = request.args.get("layout", "").strip()

    rows = []
    if periodo and len(periodo) == 6:
        try:
            # 1) registros cujo ano_mes bate com o período (mesmo critério da tela)
            q1 = (supabase.table("tab_esocial")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("ano_mes", int(periodo))
                  .neq("layout", "3000")
                  .order("data_cad", desc=True)
                  .order("hora_cad", desc=True))
            if f_layout:
                q1 = q1.eq("layout", f_layout)
            r1 = q1.execute().data or []

            # 2) registros sem ano_mes criados no mês do período
            q2 = (supabase.table("tab_esocial")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .is_("ano_mes", "null")
                  .neq("layout", "3000")
                  .gte("data_cad", periodo + "01")
                  .lte("data_cad", periodo + "31")
                  .order("data_cad", desc=True)
                  .order("hora_cad", desc=True))
            if f_layout:
                q2 = q2.eq("layout", f_layout)
            r2 = q2.execute().data or []

            seen = set()
            for r in r1 + r2:
                if r["id_esocial"] not in seen:
                    seen.add(r["id_esocial"])
                    rows.append(r)
            rows.sort(key=lambda r: (r.get("data_cad", ""), r.get("hora_cad", "")), reverse=True)
        except Exception:
            pass

    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    _LAY = {
        "1000": ("S-1000", "Empregador"),
        "1010": ("S-1010", "Rubricas"),
        "1200": ("S-1200", "Remuneração"),
        "1210": ("S-1210", "Pagamentos"),
        "1298": ("S-1298", "Reabertura"),
        "1299": ("S-1299", "Fechamento"),
        "2200": ("S-2200", "Admissão"),
        "2205": ("S-2205", "Alt.Cadastral"),
        "2206": ("S-2206", "Alt.Contrato"),
        "2230": ("S-2230", "Afastamento"),
        "2299": ("S-2299", "Desligamento"),
        "3000": ("S-3000", "Exclusão"),
    }
    _SIT_LBL = {"E": "Enviado", "X": "Com Erro", "W": "Aguardando", "G": "Gerado", "P": "Pendente"}

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    for r in rows:
        lay  = str(r.get("layout") or "")
        info = _LAY.get(lay, (f"S-{lay}", ""))
        r["_lay_codigo"] = info[0]
        r["_lay_desc"]   = info[1]
        r["_nome"]       = nomes.get(r.get("matricula"), "") if r.get("matricula") else ""
        r["_datacad"]    = _d8(r.get("data_cad"))
        _hg = str(r.get("hora_grava") or "").strip()
        _dg = str(r.get("data_grava") or "").strip()
        if len(_dg) == 8 and len(_hg) >= 4:
            r["_envio"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]} {_hg[0:2]}:{_hg[2:4]}"
        elif len(_dg) == 8:
            r["_envio"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]}"
        else:
            r["_envio"] = ""
        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()
        if recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit_label"] = _SIT_LBL.get(s, s)
        r["_recibo_curto"] = recibo[:28] if recibo else (obs[:40] if obs and not obs.startswith("AGUARDANDO:") else "")

        am = r.get("ano_mes")
        if am:
            am_s = str(am)
            r["_periodo_fmt"] = f"{am_s[4:6]}/{am_s[0:4]}" if len(am_s) == 6 else str(am)
        else:
            r["_periodo_fmt"] = ""

    periodo_fmt = f"{periodo[4:6]}/{periodo[0:4]}" if len(periodo) == 6 else periodo
    lay_desc    = _LAY.get(f_layout, (f"S-{f_layout}", ""))[0] if f_layout else "Todos os layouts"
    titulo      = f"Fila de Remessas eSocial — {periodo_fmt}  ·  {lay_desc}"

    # landscape A4 usable width: 29.7 - 4cm margins = 25.7cm
    from reportlab.lib.pagesizes import A4, landscape
    page    = landscape(A4)
    _FS     = 7   # fonte dados
    _FS_HDR = 7   # fonte cabeçalho

    def P(txt, fn="Helvetica", fs=_FS, align=0, col=colors.HexColor("#1f2937")):
        st = ParagraphStyle("x", fontName=fn, fontSize=fs, alignment=align,
                            textColor=col, leading=fs + 1)
        return Paragraph(str(txt or ""), st)

    C_HDR = colors.HexColor("#e8f5ee")
    C_LIN = colors.HexColor("#f8fafc")
    C_SUB = colors.HexColor("#64748b")

    hdr = [
        P("Layout", fn="Helvetica-Bold", fs=_FS_HDR),
        P("Matrícula · Funcionário / Período", fn="Helvetica-Bold", fs=_FS_HDR),
        P("Situação", fn="Helvetica-Bold", fs=_FS_HDR),
        P("Cadastro", fn="Helvetica-Bold", fs=_FS_HDR),
        P("Envio", fn="Helvetica-Bold", fs=_FS_HDR),
        P("Recibo / Erro", fn="Helvetica-Bold", fs=_FS_HDR),
    ]
    tbl_data = [hdr]

    for r in rows:
        mat  = f"{int(r.get('matricula') or 0):06d}" if r.get("matricula") else ""
        func = f"{mat}  {r['_nome']}" if mat and r["_nome"] else (mat or r.get("_periodo_fmt", ""))
        lay_txt = f"{r['_lay_codigo']}  {r['_lay_desc']}"
        tbl_data.append([
            P(lay_txt),
            P(func, fn="Helvetica-Bold"),
            P(r["_sit_label"], col=C_SUB),
            P(r["_datacad"], col=C_SUB),
            P(r["_envio"], col=C_SUB),
            P(r["_recibo_curto"][:22], col=C_SUB),
        ])

    # colunas somam 25.7cm (largura útil em landscape)
    col_w = [3.2*cm, 10.0*cm, 2.3*cm, 1.9*cm, 2.8*cm, 5.5*cm]

    tbl = Table(tbl_data, colWidths=col_w, repeatRows=1)
    row_bg = []
    for i in range(1, len(tbl_data)):
        row_bg.append(("BACKGROUND", (0, i), (-1, i), colors.white if i % 2 else C_LIN))
    tbl.setStyle(TableStyle([
        ("BACKGROUND",    (0, 0), (-1, 0), C_HDR),
        ("LINEBELOW",     (0, 0), (-1, 0), 0.6, colors.HexColor("#86efac")),
        ("LINEBELOW",     (0, 1), (-1, -1), 0.3, colors.HexColor("#f1f5f9")),
        ("TOPPADDING",    (0, 0), (-1, -1), 2),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
        ("LEFTPADDING",   (0, 0), (-1, -1), 4),
        ("RIGHTPADDING",  (0, 0), (-1, -1), 4),
        ("VALIGN",        (0, 0), (-1, -1), "MIDDLE"),
    ] + row_bg))

    total_p = P(f"Total: {len(rows)} remessa(s)", fn="Helvetica", fs=8,
                col=C_SUB, align=2)

    # Cabeçalho via canvas — aparece em TODAS as páginas
    _lm       = 2*cm
    _rm       = 2*cm
    _ph       = page[1]          # altura da página (landscape)
    _pw       = page[0]
    _agora    = datetime.now().strftime("%d/%m/%Y %H:%M")
    _titulo_h = titulo
    _emp_h    = f"{cnpj_fmt} — {empresa_nm}"

    def _header_todas(canvas, doc):
        _pdf_num_pagina(canvas, doc)
        canvas.saveState()
        # linha 1 — empresa (esq) e data (dir)
        y1 = _ph - 1.0*cm
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.HexColor("#374151"))
        canvas.drawString(_lm, y1, _emp_h)
        canvas.drawRightString(_pw - _rm, y1, _agora)
        # linha 2 — título centralizado
        y2 = y1 - 11
        canvas.setFont("Helvetica-Bold", 8)
        canvas.drawCentredString(_pw / 2, y2, _titulo_h)
        # linha separadora
        canvas.setStrokeColor(colors.HexColor("#374151"))
        canvas.setLineWidth(0.5)
        canvas.line(_lm, y2 - 4, _pw - _rm, y2 - 4)
        canvas.restoreState()

    _fp = [f"Período: {periodo_fmt}"]
    if f_layout:
        _fp.append(f"Layout: {lay_desc}")
    filtros_p = P("Filtros: " + "  |  ".join(_fp), fn="Helvetica", fs=7, col=C_SUB)

    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=page,
                            leftMargin=_lm, rightMargin=_rm,
                            topMargin=2.0*cm, bottomMargin=1.5*cm)
    doc.build(
        [Spacer(1, 4), tbl, Spacer(1, 6), total_p, Spacer(1, 4), filtros_p],
        onFirstPage=_header_todas, onLaterPages=_header_todas,
    )
    buf.seek(0)

    from flask import make_response
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/pdf"
    resp.headers["Content-Disposition"] = f'inline; filename="FilaRemessas_{periodo}.pdf"'
    return resp


# =========================================================
# eSocial — Re-consultar lote (genérico, qualquer layout)
# =========================================================
@app.route("/api/esocial_reconsultar_generico", methods=["POST"])
def api_esocial_reconsultar_generico():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("observacao_erro, matricula, layout")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        obs = (r_es.data[0].get("observacao_erro") or "")
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    _params_raw = ""
    protocolo_envio = ""
    if obs.startswith("AGUARDANDO:"):
        protocolo_envio = obs[len("AGUARDANDO:"):]
    elif "|AGUARDANDO:" in obs:
        for part in obs.split("|"):
            if part.startswith("PARAMS:"):
                _params_raw = part
            elif part.startswith("AGUARDANDO:"):
                protocolo_envio = part[len("AGUARDANDO:"):]
    if not protocolo_envio:
        return jsonify({"ok": False, "msg": "Registro não está aguardando."})

    try:
        r_emp = (supabase.table("tab_empresa").select("*")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        empresa = r_emp.data[0] if r_emp.data else {}
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break
        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break
        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue
        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        if cd_resp == "201" and not recibo_final and not obs_erro:
            recibo_final = protocolo_envio
        elif not recibo_final and not obs_erro:
            obs_erro = f"[{cd_resp}] {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        _ag = f"AGUARDANDO:{protocolo_envio}"
        upd["observacao_erro"] = f"{_params_raw}|{_ag}" if _params_raw else _ag
    elif obs_erro:
        upd["observacao_erro"] = (f"{_params_raw}|{obs_erro[:200]}" if _params_raw
                                  else obs_erro[:295])
    else:
        upd["observacao_erro"] = _params_raw  # sucesso: preserva PARAMS, remove AGUARDANDO
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    ok = bool(recibo_final) and not obs_erro
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


