# eSocial — Gerador de Remessa
# =========================================================
@app.route("/esocial_gerador")
def esocial_gerador():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")

    id_cliente = session.get("id_cliente")

    funcionarios = []
    try:
        funcionarios = (supabase.table("tab_cad")
                        .select("matricula, nome, situacao")
                        .eq("id_empresa", id_empresa)
                        .order("nome")
                        .execute().data or [])
        funcionarios = [f for f in funcionarios if str(f.get("situacao") or "A") == "A"]
    except Exception:
        pass

    rubricas_lista = []
    try:
        rubricas_lista = (supabase.table("tab_rubrica")
                          .select("cod_rubr,dsc_rubr,tp_rubr")
                          .in_("id_cliente", [0, id_cliente])
                          .eq("situacao", "A")
                          .order("cod_rubr")
                          .execute().data or [])
    except Exception:
        pass

    return render_template(
        "F10_eSocial_Gerador.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        funcionarios=funcionarios,
        rubricas_lista=rubricas_lista,
        anomes_atual=anomes_atual,
    )


# =========================================================
# eSocial — API: remessas com recibo (para seleção de Alteração)
# =========================================================
@app.route("/api/esocial_remessas_com_recibo")
def api_esocial_remessas_com_recibo():
    if not session.get("logado"):
        return jsonify({"ok": False, "items": []})

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")
    layout       = request.args.get("layout", "").strip()

    if not layout or not anomes_atual or len(anomes_atual) != 6:
        return jsonify({"ok": False, "msg": "Parâmetros inválidos.", "items": []})

    try:
        rows = (supabase.table("tab_esocial")
                .select("id_esocial, recibo, data_grava, hora_grava, matricula")
                .eq("id_empresa", id_empresa)
                .eq("layout", layout)
                .eq("ano_mes", int(anomes_atual))
                .order("data_grava", desc=True)
                .execute().data or [])
        rows = [r for r in rows if (r.get("recibo") or "").strip()]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)[:200], "items": []})

    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    items = []
    for r in rows:
        dg = str(r.get("data_grava") or "").strip()
        hg = str(r.get("hora_grava") or "").strip()
        data_fmt = f"{dg[6:8]}/{dg[4:6]}/{dg[0:4]}" if len(dg) == 8 else "—"
        if len(hg) >= 4:
            data_fmt += f" {hg[0:2]}:{hg[2:4]}"
        items.append({
            "id_esocial": r["id_esocial"],
            "recibo":     (r.get("recibo") or "").strip(),
            "data_fmt":   data_fmt,
            "nome":       nomes.get(r.get("matricula"), "—") if r.get("matricula") else "—",
        })

    am_s = anomes_atual
    periodo_fmt = f"{am_s[4:6]}/{am_s[0:4]}" if len(am_s) == 6 else anomes_atual
    return jsonify({"ok": True, "items": items, "periodo": periodo_fmt})


@app.route("/api/esocial_gerador_criar", methods=["POST"])
def api_esocial_gerador_criar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    id_empresa   = _get_id_empresa()
    id_cliente   = session.get("id_cliente")
    anomes_atual = str(session.get("anomes_atual") or "")
    data         = request.get_json(force=True) or {}

    import json as _json_g

    layout     = str(data.get("layout", "")).strip()
    matricula  = data.get("matricula")
    operacao   = "A" if str(data.get("operacao", "I")).upper() == "A" else "I"
    recibo_ref = (data.get("recibo_ref") or "").strip()
    rubricas   = data.get("rubricas", [])   # usado apenas para S-1010

    _LAYOUTS_FUNC    = {"2200", "2205", "2206", "2220", "2230", "2299"}
    _LAYOUTS_VALIDOS = {"1000", "1005", "1010", "1020",
                        "2200", "2205", "2206", "2220", "2230", "2299",
                        "1200", "1210", "1298", "1299", "3000"}

    if layout not in _LAYOUTS_VALIDOS:
        return jsonify({"ok": False, "msg": f"Layout inválido: {layout}"})

    if layout in _LAYOUTS_FUNC and not matricula:
        return jsonify({"ok": False, "msg": "Funcionário é obrigatório para este layout."})

    if layout == "1010" and not rubricas:
        return jsonify({"ok": False, "msg": "Selecione ao menos uma rubrica para o S-1010."})

    agora = datetime.now()
    try:
        ano_mes_val = int(anomes_atual) if anomes_atual and len(anomes_atual) == 6 else None
        ini_valid = f"{anomes_atual[:4]}-{anomes_atual[4:6]}" if len(anomes_atual) == 6 else ""

        ins = {
            "id_cliente": id_cliente,
            "id_empresa": id_empresa,
            "data_cad":   agora.strftime("%Y%m%d"),
            "hora_cad":   agora.strftime("%H%M"),
            "id_remessa": agora.strftime("%Y%m%d%H%M%S"),
            "folha_tipo": "N",
            "layout":     layout,
            "codigo2":    0,
            "operacao":   operacao,
            "recibo_ref": recibo_ref or None,
        }
        if ano_mes_val:
            ins["ano_mes"] = ano_mes_val
        if matricula:
            ins["matricula"] = int(matricula)

        # S-1010: grava PARAMS com as rubricas selecionadas
        if layout == "1010":
            try:
                rubricas_int = [int(c) for c in rubricas]
            except Exception:
                return jsonify({"ok": False, "msg": "Códigos de rubrica inválidos."})
            params = _json_g.dumps(
                {"ini": ini_valid, "fim": "", "tpAmb": "1", "rubricas": rubricas_int},
                ensure_ascii=False
            )
            ins["observacao_erro"] = f"PARAMS:{params}"

        res = supabase.table("tab_esocial").insert(ins).execute()
        id_reg = res.data[0]["id_esocial"]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao criar remessa: {e}"})

    gravar_log("ESOCIAL",
               f"Remessa S-{layout} criada pelo Gerador: id={id_reg} mat={matricula}",
               matricula=int(matricula) if matricula else None)

    return jsonify({
        "ok":         True,
        "id_esocial": id_reg,
        "layout":     layout,
        "matricula":  matricula,
        "msg":        f"Remessa S-{layout} criada com sucesso.",
    })


@app.route("/api/esocial_excluir", methods=["POST"])
def api_esocial_excluir():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    id_empresa = _get_id_empresa()
    data       = request.get_json(force=True) or {}
    id_esocial = data.get("id_esocial")

    if not id_esocial:
        return jsonify({"ok": False, "msg": "id_esocial ausente."})

    try:
        rows = (supabase.table("tab_esocial")
                .select("id_esocial, recibo, layout, matricula")
                .eq("id_esocial", id_esocial)
                .eq("id_empresa", id_empresa)
                .execute().data or [])

        if not rows:
            return jsonify({"ok": False, "msg": "Remessa não encontrada."})

        r      = rows[0]
        recibo = (r.get("recibo") or "").strip()
        if recibo:
            return jsonify({"ok": False, "msg": "Remessa já possui recibo — não pode ser excluída."})

        supabase.table("tab_esocial").delete().eq("id_esocial", id_esocial).execute()

        gravar_log("ESOCIAL",
                   f"Remessa S-{r.get('layout')} id={id_esocial} excluída pelo usuário",
                   matricula=r.get("matricula"))

        return jsonify({"ok": True})

    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro: {e}"})


# =========================================================
# eSocial S-1200 — TELA DE LISTAGEM
# =========================================================
@app.route("/esocial_s1200")
def esocial_s1200():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")
    f_sit        = request.args.get("sit", "")
    f_anomes     = request.args.get("anomes", "")
    f_tipo       = request.args.get("tipo", "")

    rows = []
    try:
        q = (supabase.table("tab_esocial")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("layout", "1200")
             .order("ano_mes", desc=True)
             .order("data_cad", desc=True)
             .order("hora_cad", desc=True))
        if f_anomes:
            q = q.eq("ano_mes", int(f_anomes))
        if f_tipo:
            q = q.eq("folha_tipo", f_tipo)
        rows = q.execute().data or []
    except Exception:
        rows = []

    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    def _fmt_anomes(v):
        s = str(int(v)).zfill(6) if v else ""
        return f"{s[4:6]}/{s[:4]}" if len(s) == 6 else str(v or "")

    _TP_FOLHA = {"N": "Normal", "1": "13º Sal.", "A": "Adiant. 13º", "F": "Férias", "R": "Rescisão"}
    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    for r in rows:
        r["_nome"]          = nomes.get(r.get("matricula"), "—")
        r["_datacad_fmt"]   = _d8(r.get("data_cad"))
        r["_datagrava_fmt"] = _d8(r.get("data_grava"))
        r["_periodo"]       = _fmt_anomes(r.get("ano_mes"))
        r["_tipo_label"]    = _TP_FOLHA.get(str(r.get("folha_tipo") or "N"), str(r.get("folha_tipo") or ""))

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = obs[len("AGUARDANDO:"):]
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    if f_sit:
        rows = [r for r in rows if r.get("_sit") == f_sit]

    contagens = {k: sum(1 for r in rows if r["_sit"] == k) for k in "PGEXWD"}

    periodos_disp = []
    try:
        _prows = (supabase.table("tab_esocial")
                  .select("ano_mes")
                  .eq("id_empresa", id_empresa)
                  .eq("layout", "1200")
                  .order("ano_mes", desc=True)
                  .execute().data or [])
        _seen = set()
        for _p in _prows:
            _v = _p.get("ano_mes")
            if _v and _v not in _seen:
                _seen.add(_v)
                periodos_disp.append({"valor": str(_v), "label": _fmt_anomes(_v)})
    except Exception:
        pass

    return render_template(
        "F10_eSocial_S1200.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows,
        f_sit=f_sit, f_anomes=f_anomes, f_anomes_fmt=_fmt_anomes(f_anomes) if f_anomes else "", f_tipo=f_tipo,
        contagens=contagens,
        total=len(rows),
        periodos_disp=periodos_disp,
        TP_FOLHA=_TP_FOLHA,
        anomes_atual=anomes_atual,
    )


# =========================================================
# eSocial S-1200 — API: gerar + assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s1200_enviar", methods=["POST"])
def api_esocial_s1200_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    # 1. Registro na tab_esocial
    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1200")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro S-1200 não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    matricula  = es.get("matricula")
    ano_mes    = es.get("ano_mes")
    folha_tipo = str(es.get("folha_tipo") or "N")

    # 2. Dados do funcionário
    try:
        r_func = (supabase.table("tab_cad")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    # 3. Itens de movimento (remuneração do período)
    mov_items = []
    try:
        _qm = (supabase.table("tab_mov")
               .select("cod_verba, valor")
               .eq("id_empresa", id_empresa)
               .eq("matricula", matricula)
               .eq("folha", int(ano_mes))
               .eq("folha_tipo", folha_tipo)
               .eq("situacao", "A"))
        _id_cliente = session.get("id_cliente")
        if _id_cliente:
            _qm = _qm.eq("id_cliente", _id_cliente)
        _rows_mov = _qm.execute().data or []
        # Agrega por cod_verba
        _agg = {}
        for _r in _rows_mov:
            _c = str(_r.get("cod_verba") or "")
            _v = int(_r.get("valor") or 0)
            _agg[_c] = _agg.get(_c, 0) + _v
        mov_items = [{"cod_verba": k, "valor": v} for k, v in _agg.items() if v != 0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar movimento: {e}"})

    # 4. Empresa + certificado
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False,
                        "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    # 5. Gerar XML
    try:
        xml_str = _gerar_xml_s1200(func, mov_items, empresa, ano_mes, folha_tipo, tpAmb)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    # Diretório de diagnóstico
    import os as _os2
    _now2    = datetime.now()
    _dir_xml = _os2.path.join(_os2.path.dirname(__file__),
                               "eSocial_XML", _now2.strftime("%Y"),
                               _now2.strftime("%Y-%m"), str(id_empresa).zfill(6))
    _os2.makedirs(_dir_xml, exist_ok=True)
    _ts   = _now2.strftime("%Y%m%d_%H%M%S")
    _pref = _os2.path.join(_dir_xml, f"S1200_{matricula}_{_ts}")

    try:
        with open(f"{_pref}_1_evento.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_str)
    except Exception:
        pass

    # 6. Assinar
    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    try:
        with open(f"{_pref}_2_assinado.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_assinado)
    except Exception:
        pass

    # 7. Montar lote  (S-1200 = Grupo 3 — Periódicos)
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str, grupo="3")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    try:
        with open(f"{_pref}_3_lote.xml", "w", encoding="utf-8") as _f:
            _f.write(lote_xml)
    except Exception:
        pass

    # 8. Enviar
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        with open(f"{_pref}_4_soap_envio.xml", "w", encoding="utf-8") as _f:
            _f.write(soap_env)
    except Exception:
        pass

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        try:
            with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
                _f.write(detalhe)
        except Exception:
            pass
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    try:
        with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
            _f.write(resp_envio)
    except Exception:
        pass

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]

    if not protocolo_envio:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.", "detalhe": analise["erro"]})

    agora = datetime.now()
    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # 9. Consultar resultado (até 3×)
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            with open(f"{_pref}_6_resultado_consulta.xml", "w", encoding="utf-8") as _f:
                _f.write(resp_cons)
        except Exception:
            pass

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))

    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1200 enviado: mat={matricula} anomes={ano_mes} nrRec={recibo_final} cd={cd_resp}",
               matricula=matricula)

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg": ("eSocial ainda processando. Use Re-consultar." if aguardando
                else obs_erro or f"Enviado com sucesso. Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1200 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s1200_reconsultar", methods=["POST"])
def api_esocial_s1200_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1200")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    obs = (es.get("observacao_erro") or "").strip()
    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está em estado Aguardando."})
    protocolo = obs[len("AGUARDANDO:"):]

    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("cert_pfx_b64, cert_senha_enc")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        emp = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    pfx_bytes = base64.b64decode(emp.get("cert_pfx_b64") or "")
    senha_str = _cert_decrypt(emp.get("cert_senha_enc") or "")
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""

    for tentativa in range(3):
        if tentativa:
            time.sleep(10)
        soap_cons = _soap_consultar(protocolo)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1200 reconsulta: mat={es.get('matricula')} nrRec={recibo_final} cd={cd_resp}",
               matricula=es.get("matricula"))

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1210 — TELA DE LISTAGEM
# =========================================================
@app.route("/esocial_s1210")
def esocial_s1210():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")
    f_sit        = request.args.get("sit", "")
    f_anomes     = request.args.get("anomes", "")
    f_tipo       = request.args.get("tipo", "")

    rows = []
    try:
        q = (supabase.table("tab_esocial")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("layout", "1210")
             .order("ano_mes", desc=True)
             .order("data_cad", desc=True)
             .order("hora_cad", desc=True))
        if f_anomes:
            q = q.eq("ano_mes", int(f_anomes))
        if f_tipo:
            q = q.eq("folha_tipo", f_tipo)
        rows = q.execute().data or []
    except Exception:
        rows = []

    mats = list({r["matricula"] for r in rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    # Busca S-1200 correspondentes para exibir status
    s1200_map = {}
    try:
        _anomes_list = list({r.get("ano_mes") for r in rows if r.get("ano_mes")})
        if mats and _anomes_list:
            _s12_rows = (supabase.table("tab_esocial")
                         .select("matricula, ano_mes, folha_tipo, recibo, observacao_erro")
                         .eq("id_empresa", id_empresa)
                         .eq("layout", "1200")
                         .in_("matricula", mats)
                         .in_("ano_mes", _anomes_list)
                         .execute().data or [])
            for s in _s12_rows:
                _k = (s.get("matricula"), s.get("ano_mes"), str(s.get("folha_tipo") or "N"))
                s1200_map[_k] = s
    except Exception:
        pass

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    def _fmt_anomes(v):
        s = str(int(v)).zfill(6) if v else ""
        return f"{s[4:6]}/{s[:4]}" if len(s) == 6 else str(v or "")

    _TP_FOLHA = {"N": "Normal", "1": "13º Sal.", "A": "Adiant. 13º", "F": "Férias", "R": "Rescisão"}
    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }

    for r in rows:
        r["_nome"]          = nomes.get(r.get("matricula"), "—")
        r["_datacad_fmt"]   = _d8(r.get("data_cad"))
        r["_datagrava_fmt"] = _d8(r.get("data_grava"))
        _hg = str(r.get("hora_grava") or "").strip()
        _dg = str(r.get("data_grava") or "").strip()
        if len(_dg) == 8 and len(_hg) >= 4:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]} {_hg[0:2]}:{_hg[2:4]}"
        elif len(_dg) == 8:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]}"
        else:
            r["_envio_fmt"] = ""
        r["_periodo"]       = _fmt_anomes(r.get("ano_mes"))
        r["_tipo_label"]    = _TP_FOLHA.get(str(r.get("folha_tipo") or "N"), str(r.get("folha_tipo") or ""))

        _k = (r.get("matricula"), r.get("ano_mes"), str(r.get("folha_tipo") or "N"))
        s12 = s1200_map.get(_k, {})
        r["_s1200_recibo"]  = (s12.get("recibo") or "").strip()
        r["_s1200_enviado"] = bool(r["_s1200_recibo"])

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = obs[len("AGUARDANDO:"):]
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    if f_sit:
        rows = [r for r in rows if r.get("_sit") == f_sit]

    contagens = {k: sum(1 for r in rows if r["_sit"] == k) for k in "PGEXWD"}

    periodos_disp = []
    try:
        _prows = (supabase.table("tab_esocial")
                  .select("ano_mes")
                  .eq("id_empresa", id_empresa)
                  .eq("layout", "1210")
                  .order("ano_mes", desc=True)
                  .execute().data or [])
        _seen = set()
        for _p in _prows:
            _v = _p.get("ano_mes")
            if _v and _v not in _seen:
                _seen.add(_v)
                periodos_disp.append({"valor": str(_v), "label": _fmt_anomes(_v)})
    except Exception:
        pass

    dtpgto_default = ""
    try:
        _ref = f_anomes or (periodos_disp[0]["valor"] if periodos_disp else "")
        if _ref:
            _am2 = str(int(_ref)).zfill(6)
            _yr, _mo = int(_am2[:4]), int(_am2[4:6])
            _mo += 1
            if _mo > 12:
                _mo, _yr = 1, _yr + 1
            dtpgto_default = f"{_yr:04d}-{_mo:02d}-05"
    except Exception:
        pass

    return render_template(
        "F10_eSocial_S1210.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows,
        f_sit=f_sit, f_anomes=f_anomes,
        f_anomes_fmt=_fmt_anomes(f_anomes) if f_anomes else "",
        f_tipo=f_tipo,
        contagens=contagens,
        total=len(rows),
        periodos_disp=periodos_disp,
        TP_FOLHA=_TP_FOLHA,
        dtpgto_default=dtpgto_default,
        anomes_atual=anomes_atual,
    )


# =========================================================
# eSocial S-1210 — API: gerar + assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s1210_enviar", methods=["POST"])
def api_esocial_s1210_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))
    dtPgto     = str(data.get("dtPgto", "")).strip()

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})
    if not dtPgto:
        return jsonify({"ok": False, "msg": "Data de pagamento não informada."})

    # 1. Registro S-1210
    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1210")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro S-1210 não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    matricula  = es.get("matricula")
    ano_mes    = es.get("ano_mes")
    folha_tipo = str(es.get("folha_tipo") or "N")

    # 2. Recibo do S-1200 correspondente
    try:
        r_s1200 = (supabase.table("tab_esocial")
                   .select("recibo")
                   .eq("id_empresa", id_empresa)
                   .eq("layout", "1200")
                   .eq("matricula", matricula)
                   .eq("ano_mes", int(ano_mes))
                   .eq("folha_tipo", folha_tipo)
                   .not_.is_("recibo", "null")
                   .neq("recibo", "")
                   .limit(1).execute())
        if not r_s1200.data:
            return jsonify({"ok": False,
                            "msg": "S-1200 ainda não enviado. Envie o S-1200 primeiro."})
        recibo_s1200 = r_s1200.data[0]["recibo"].strip()
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar S-1200: {e}"})

    # 3. Funcionário
    try:
        r_func = (supabase.table("tab_cad")
                  .select("*")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    # 4. Totais do período
    totais = {}
    try:
        _qt = (supabase.table("tab_total")
               .select("valor_liquido, valor_base_inss_comlimite, valor_irrf_basetabela")
               .eq("id_empresa", id_empresa)
               .eq("matricula", matricula)
               .eq("folha", int(ano_mes))
               .eq("folha_tipo", folha_tipo)
               .limit(1).execute())
        if _qt.data:
            totais = _qt.data[0]
    except Exception:
        pass

    # 5. Empresa + certificado
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    # 6. Gerar XML
    try:
        xml_str = _gerar_xml_s1210(func, empresa, ano_mes, folha_tipo, tpAmb,
                                   dtPgto, recibo_s1200, totais)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    import os as _os2
    _now2    = datetime.now()
    _dir_xml = _os2.path.join(_os2.path.dirname(__file__),
                               "eSocial_XML", _now2.strftime("%Y"),
                               _now2.strftime("%Y-%m"), str(id_empresa).zfill(6))
    _os2.makedirs(_dir_xml, exist_ok=True)
    _ts   = _now2.strftime("%Y%m%d_%H%M%S")
    _pref = _os2.path.join(_dir_xml, f"S1210_{matricula}_{_ts}")

    try:
        with open(f"{_pref}_1_evento.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_str)
    except Exception:
        pass

    # 7. Assinar
    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    try:
        with open(f"{_pref}_2_assinado.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_assinado)
    except Exception:
        pass

    # 8. Montar lote (Grupo 3 — Periódicos)
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str, grupo="3")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    try:
        with open(f"{_pref}_3_lote.xml", "w", encoding="utf-8") as _f:
            _f.write(lote_xml)
    except Exception:
        pass

    # 9. Enviar
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        with open(f"{_pref}_4_soap_envio.xml", "w", encoding="utf-8") as _f:
            _f.write(soap_env)
    except Exception:
        pass

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        try:
            with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
                _f.write(detalhe)
        except Exception:
            pass
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    try:
        with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
            _f.write(resp_envio)
    except Exception:
        pass

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]

    if not protocolo_envio:
        agora = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava":      agora.strftime("%Y%m%d"),
            "hora_grava":      agora.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.", "detalhe": analise["erro"]})

    agora = datetime.now()
    supabase.table("tab_esocial").update({
        "data_grava": agora.strftime("%Y%m%d"),
        "hora_grava": agora.strftime("%H%M"),
    }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # 10. Consultar resultado (até 3×)
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            with open(f"{_pref}_6_resultado_consulta.xml", "w", encoding="utf-8") as _f:
                _f.write(resp_cons)
        except Exception:
            pass

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1210 enviado: mat={matricula} anomes={ano_mes} nrRec={recibo_final} cd={cd_resp}",
               matricula=matricula)

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg": ("eSocial ainda processando. Use Re-consultar." if aguardando
                else obs_erro or f"Enviado com sucesso. Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1210 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s1210_reconsultar", methods=["POST"])
def api_esocial_s1210_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1210")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    obs = (es.get("observacao_erro") or "").strip()
    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está em estado Aguardando."})
    protocolo = obs[len("AGUARDANDO:"):]

    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("cert_pfx_b64, cert_senha_enc")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        emp = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    pfx_bytes = base64.b64decode(emp.get("cert_pfx_b64") or "")
    senha_str = _cert_decrypt(emp.get("cert_senha_enc") or "")
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        if tentativa:
            time.sleep(10)
        soap_cons = _soap_consultar(protocolo)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1210 reconsulta: mat={es.get('matricula')} nrRec={recibo_final} cd={cd_resp}",
               matricula=es.get("matricula"))

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1299 — GERADOR DE XML
# =========================================================
def _gerar_xml_s1299(empresa, ano_mes, ind_apuracao, evt_remun, evt_pgtos, tpAmb="1"):
    """Gera string XML do S-1299 (Fechamento dos Eventos Periódicos) - schema evtFechaEvPer/v_S_01_03_00."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    _am      = str(int(ano_mes)).zfill(6)
    per_apur = f"{_am[:4]}-{_am[4:6]}"

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtFechaEvPer/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtFechaEvPer/v_S_01_03_00 evtFechaEvPer_v_S_01_03_00.xsd">
  <evtFechaEvPer Id="{evt_id}">
    <ideEvento>
      <indApuracao>{x(ind_apuracao)}</indApuracao>
      <perApur>{per_apur}</perApur>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>Folha10-Simples</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
    <infoFech>
      <evtRemun>{x(evt_remun)}</evtRemun>
      <evtPgtos>{x(evt_pgtos)}</evtPgtos>
      <evtComProd>N</evtComProd>
      <evtContratAvNP>N</evtContratAvNP>
      <evtInfoComplPer>N</evtInfoComplPer>
    </infoFech>
  </evtFechaEvPer>
</eSocial>"""


# =========================================================
# eSocial S-1299 — TELA
# =========================================================
@app.route("/esocial_s1299")
def esocial_s1299():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")

    rows = []
    try:
        q = (supabase.table("tab_esocial")
             .select("*")
             .eq("id_empresa", id_empresa)
             .eq("layout", "1299")
             .order("data_cad", desc=True)
             .order("hora_cad", desc=True))
        if anomes_atual:
            q = q.eq("ano_mes", int(anomes_atual))
        rows = q.execute().data or []
    except Exception:
        rows = []

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    def _fmt_anomes(v):
        s = str(int(v)).zfill(6) if v else ""
        return f"{s[4:6]}/{s[:4]}" if len(s) == 6 else str(v or "")

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }
    _TIPO_LABEL = {"N": "Mensal",  "1": "Anual / 13º"}

    for r in rows:
        r["_periodo"]      = _fmt_anomes(r.get("ano_mes"))
        r["_datacad_fmt"]  = _d8(r.get("data_cad"))
        r["_datagrava_fmt"]= _d8(r.get("data_grava"))
        _hg = str(r.get("hora_grava") or "").strip()
        _dg = str(r.get("data_grava") or "").strip()
        if len(_dg) == 8 and len(_hg) >= 4:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]} {_hg[0:2]}:{_hg[2:4]}"
        elif len(_dg) == 8:
            r["_envio_fmt"] = f"{_dg[6:8]}/{_dg[4:6]}/{_dg[2:4]}"
        else:
            r["_envio_fmt"] = ""
        r["_tipo_label"]   = _TIPO_LABEL.get(str(r.get("folha_tipo") or "N"), "Mensal")

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = obs[len("AGUARDANDO:"):]
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    return render_template(
        "F10_eSocial_S1299.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows,
        total=len(rows),
        anomes_atual=anomes_atual,
    )


# =========================================================
# eSocial S-1299 — API: gerar + assinar + enviar + consultar
# =========================================================
@app.route("/api/esocial_s1299_enviar", methods=["POST"])
def api_esocial_s1299_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}

    ano_mes        = str(data.get("ano_mes", "")).strip()
    ind_apuracao   = str(data.get("ind_apuracao", "1")).strip()
    ind_exist_info = str(data.get("ind_exist_info", "S")).strip()
    evt_remun_raw  = str(data.get("evt_remun", "S")).strip().upper()
    evt_pgtos_raw  = str(data.get("evt_pgtos", "S")).strip().upper()
    tpAmb          = str(data.get("tpAmb", "1")).strip()

    if not ano_mes:
        return jsonify({"ok": False, "msg": "Período não informado."})

    # Empresa + certificado
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    # Reutiliza registro existente ou cria novo
    agora = datetime.now()
    sem_mov_flag = 1 if ind_exist_info == "N" else 0
    folha_tp     = "1" if ind_apuracao == "2" else "N"
    id_cliente   = session.get("id_cliente")
    try:
        _exist = (supabase.table("tab_esocial")
                  .select("id_esocial")
                  .eq("id_empresa", id_empresa)
                  .eq("layout", "1299")
                  .eq("ano_mes", int(ano_mes))
                  .eq("folha_tipo", folha_tp)
                  .eq("codigo2", sem_mov_flag)
                  .order("data_cad", desc=True)
                  .limit(1).execute())
        if _exist.data:
            id_reg = _exist.data[0]["id_esocial"]
            supabase.table("tab_esocial").update({
                "recibo":          "",
                "observacao_erro": "",
                "data_grava":      "",
                "hora_grava":      "",
                "id_remessa":      agora.strftime("%Y%m%d%H%M%S"),
            }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        else:
            ins = {
                "id_cliente": id_cliente,
                "id_empresa": id_empresa,
                "data_cad":   agora.strftime("%Y%m%d"),
                "hora_cad":   agora.strftime("%H%M"),
                "id_remessa": agora.strftime("%Y%m%d%H%M%S"),
                "ano_mes":    int(ano_mes),
                "folha_tipo": folha_tp,
                "layout":     "1299",
                "matricula":  0,
                "codigo2":    sem_mov_flag,
            }
            res_ins = supabase.table("tab_esocial").insert(ins).execute()
            id_reg  = res_ins.data[0]["id_esocial"]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao criar/atualizar registro: {e}"})

    # Flags de eventos: sem movimento → ambos N; senão usa o que veio do formulário
    sem_mov = (ind_exist_info == "N")
    if sem_mov:
        evt_remun = "N"
        evt_pgtos = "N"
    else:
        evt_remun = "S" if evt_remun_raw == "S" else "N"
        evt_pgtos = "S" if evt_pgtos_raw == "S" else "N"

    # Gerar XML
    try:
        xml_str = _gerar_xml_s1299(empresa, ano_mes, ind_apuracao,
                                   evt_remun, evt_pgtos, tpAmb)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    import os as _os2
    _now2    = datetime.now()
    _dir_xml = _os2.path.join(_os2.path.dirname(__file__),
                               "eSocial_XML", _now2.strftime("%Y"),
                               _now2.strftime("%Y-%m"), str(id_empresa).zfill(6))
    _os2.makedirs(_dir_xml, exist_ok=True)
    _ts   = _now2.strftime("%Y%m%d_%H%M%S")
    _pref = _os2.path.join(_dir_xml, f"S1299_{ano_mes}_{_ts}")

    try:
        with open(f"{_pref}_1_evento.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_str)
    except Exception:
        pass

    # Assinar
    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    try:
        with open(f"{_pref}_2_assinado.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_assinado)
    except Exception:
        pass

    # Montar lote (S-1299 = Grupo 3 — Periódicos)
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str, grupo="3")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    try:
        with open(f"{_pref}_3_lote.xml", "w", encoding="utf-8") as _f:
            _f.write(lote_xml)
    except Exception:
        pass

    # Enviar
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        with open(f"{_pref}_4_soap_envio.xml", "w", encoding="utf-8") as _f:
            _f.write(soap_env)
    except Exception:
        pass

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        try:
            with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
                _f.write(detalhe)
        except Exception:
            pass
        supabase.table("tab_esocial").update({"observacao_erro": detalhe[:295]})\
            .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    try:
        with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
            _f.write(resp_envio)
    except Exception:
        pass

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]

    if not protocolo_envio:
        agora2 = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava":      agora2.strftime("%Y%m%d"),
            "hora_grava":      agora2.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.",
                        "detalhe": analise["erro"], "id_esocial": id_reg})

    agora2 = datetime.now()
    supabase.table("tab_esocial").update({
        "data_grava": agora2.strftime("%Y%m%d"),
        "hora_grava": agora2.strftime("%H%M"),
    }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    # Consultar resultado (até 3×)
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            with open(f"{_pref}_6_resultado_consulta.xml", "w", encoding="utf-8") as _f:
                _f.write(resp_cons)
        except Exception:
            pass

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1299 enviado: anomes={ano_mes} indExistInfo={ind_exist_info} nrRec={recibo_final} cd={cd_resp}")

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "id_esocial": id_reg,
        "msg": ("eSocial ainda processando. Use Re-consultar." if aguardando
                else obs_erro or f"Enviado com sucesso. Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1299 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s1299_reconsultar", methods=["POST"])
def api_esocial_s1299_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1299")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    obs = (es.get("observacao_erro") or "").strip()
    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está em estado Aguardando."})
    protocolo = obs[len("AGUARDANDO:"):]

    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("cert_pfx_b64, cert_senha_enc")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        emp = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    pfx_bytes = base64.b64decode(emp.get("cert_pfx_b64") or "")
    senha_str = _cert_decrypt(emp.get("cert_senha_enc") or "")
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        if tentativa:
            time.sleep(10)
        soap_cons = _soap_consultar(protocolo)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1299 reconsulta: id={id_reg} nrRec={recibo_final} cd={cd_resp}")

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1298 — GERADOR DE XML
# =========================================================
def _gerar_xml_s1298(empresa, ano_mes, ind_apuracao, tpAmb="1"):
    """Gera string XML do S-1298 (Reabertura dos Eventos Periódicos) - schema evtReabreEvPer/v_S_01_03_00."""
    import re
    from xml.sax.saxutils import escape as _esc
    from datetime import datetime as _dt

    def dg(v):
        return re.sub(r'\D', '', str(v or ''))

    def x(v):
        return _esc(str(v or ''))

    cnpj_emp  = dg(empresa.get('cnpj', ''))
    cnpj_raiz = cnpj_emp[:8]
    _now      = _dt.now()
    evt_id    = f"ID1{cnpj_raiz.ljust(14,'0')}{_now.strftime('%Y%m%d%H%M%S')}00001"

    _am      = str(int(ano_mes)).zfill(6)
    per_apur = f"{_am[:4]}-{_am[4:6]}"

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<eSocial xmlns="http://www.esocial.gov.br/schema/evt/evtReabreEvPer/v_S_01_03_00"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://www.esocial.gov.br/schema/evt/evtReabreEvPer/v_S_01_03_00 evtReabreEvPer_v_S_01_03_00.xsd">
  <evtReabreEvPer Id="{evt_id}">
    <ideEvento>
      <indApuracao>{x(ind_apuracao)}</indApuracao>
      <perApur>{per_apur}</perApur>
      <tpAmb>{x(tpAmb)}</tpAmb>
      <procEmi>1</procEmi>
      <verProc>Folha10-Simples</verProc>
    </ideEvento>
    <ideEmpregador>
      <tpInsc>1</tpInsc>
      <nrInsc>{x(cnpj_raiz)}</nrInsc>
    </ideEmpregador>
  </evtReabreEvPer>
</eSocial>"""


# =========================================================
# eSocial S-1298 — TELA
# =========================================================
@app.route("/esocial_s1298")
def esocial_s1298():
    if not session.get("logado"):
        return redirect("/")

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")

    rows = []
    try:
        rows = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_empresa", id_empresa)
                .eq("layout", "1298")
                .order("ano_mes", desc=True)
                .order("data_cad", desc=True)
                .order("hora_cad", desc=True)
                .execute().data or [])
    except Exception:
        rows = []

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    def _fmt_anomes(v):
        s = str(int(v)).zfill(6) if v else ""
        return f"{s[4:6]}/{s[:4]}" if len(s) == 6 else str(v or "")

    _SIT = {
        "E": ("Enviado",    "sit-enviado"),
        "D": ("Excluído",   "sit-excluido"),
        "X": ("Com Erro",   "sit-erro"),
        "W": ("Aguardando", "sit-aguardando"),
        "G": ("Gerado",     "sit-gerado"),
        "P": ("Pendente",   "sit-pendente"),
    }
    _TIPO_LABEL = {"N": "Mensal", "1": "Anual / 13º"}

    for r in rows:
        r["_periodo"]      = _fmt_anomes(r.get("ano_mes"))
        r["_datacad_fmt"]  = _d8(r.get("data_cad"))
        r["_datagrava_fmt"]= _d8(r.get("data_grava"))
        r["_tipo_label"]   = _TIPO_LABEL.get(str(r.get("folha_tipo") or "N"), "Mensal")

        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        dgrava = (r.get("data_grava") or "").strip()

        if recibo and obs == "EXCLUIDO":
            s = "D"
        elif recibo:
            s = "E"
        elif obs.startswith("AGUARDANDO:"):
            s = "W"
            r["_protocolo"] = obs[len("AGUARDANDO:"):]
        elif obs:
            s = "X"
        elif dgrava:
            s = "G"
        else:
            s = "P"
        r["_sit"]       = s
        r["_sit_label"] = _SIT[s][0]
        r["_sit_class"] = _SIT[s][1]

    return render_template(
        "F10_eSocial_S1298.html",
        versao=ler_versao(),
        nome=session.get("nome", ""),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        rows=rows,
        total=len(rows),
        anomes_atual=anomes_atual,
    )


# =========================================================
# eSocial S-1298 — API: gerar + assinar + enviar
# =========================================================
@app.route("/api/esocial_s1298_enviar", methods=["POST"])
def api_esocial_s1298_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}

    ano_mes      = str(data.get("ano_mes", "")).strip()
    ind_apuracao = str(data.get("ind_apuracao", "1")).strip()
    tpAmb        = str(data.get("tpAmb", "1")).strip()

    if not ano_mes:
        return jsonify({"ok": False, "msg": "Período não informado."})

    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*").eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False, "msg": "Certificado digital não configurado."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    agora      = datetime.now()
    folha_tp   = "1" if ind_apuracao == "2" else "N"
    id_cliente = session.get("id_cliente")
    try:
        _exist = (supabase.table("tab_esocial")
                  .select("id_esocial")
                  .eq("id_empresa", id_empresa)
                  .eq("layout", "1298")
                  .eq("ano_mes", int(ano_mes))
                  .eq("folha_tipo", folha_tp)
                  .order("data_cad", desc=True)
                  .limit(1).execute())
        if _exist.data:
            id_reg = _exist.data[0]["id_esocial"]
            supabase.table("tab_esocial").update({
                "recibo":          "",
                "observacao_erro": "",
                "data_grava":      "",
                "hora_grava":      "",
                "id_remessa":      agora.strftime("%Y%m%d%H%M%S"),
            }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        else:
            ins = {
                "id_cliente": id_cliente,
                "id_empresa": id_empresa,
                "data_cad":   agora.strftime("%Y%m%d"),
                "hora_cad":   agora.strftime("%H%M"),
                "id_remessa": agora.strftime("%Y%m%d%H%M%S"),
                "ano_mes":    int(ano_mes),
                "folha_tipo": folha_tp,
                "layout":     "1298",
                "matricula":  0,
                "codigo2":    0,
            }
            res_ins = supabase.table("tab_esocial").insert(ins).execute()
            id_reg  = res_ins.data[0]["id_esocial"]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao criar/atualizar registro: {e}"})

    try:
        xml_str = _gerar_xml_s1298(empresa, ano_mes, ind_apuracao, tpAmb)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    import os as _os2
    _now2    = datetime.now()
    _dir_xml = _os2.path.join(_os2.path.dirname(__file__),
                               "eSocial_XML", _now2.strftime("%Y"),
                               _now2.strftime("%Y-%m"), str(id_empresa).zfill(6))
    _os2.makedirs(_dir_xml, exist_ok=True)
    _ts   = _now2.strftime("%Y%m%d_%H%M%S")
    _pref = _os2.path.join(_dir_xml, f"S1298_{ano_mes}_{_ts}")

    try:
        with open(f"{_pref}_1_evento.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_str)
    except Exception:
        pass

    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    try:
        with open(f"{_pref}_2_assinado.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_assinado)
    except Exception:
        pass

    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str, grupo="3")
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    try:
        with open(f"{_pref}_3_lote.xml", "w", encoding="utf-8") as _f:
            _f.write(lote_xml)
    except Exception:
        pass

    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        with open(f"{_pref}_4_soap_envio.xml", "w", encoding="utf-8") as _f:
            _f.write(soap_env)
    except Exception:
        pass

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        detalhe = str(e)
        try:
            with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
                _f.write(detalhe)
        except Exception:
            pass
        supabase.table("tab_esocial").update({"observacao_erro": detalhe[:295]})\
            .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": detalhe})

    try:
        with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
            _f.write(resp_envio)
    except Exception:
        pass

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]

    if not protocolo_envio:
        agora2 = datetime.now()
        supabase.table("tab_esocial").update({
            "data_grava":      agora2.strftime("%Y%m%d"),
            "hora_grava":      agora2.strftime("%H%M"),
            "observacao_erro": analise["erro"][:295],
        }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()
        return jsonify({"ok": False, "msg": "eSocial recusou o envio.",
                        "detalhe": analise["erro"], "id_esocial": id_reg})

    agora2 = datetime.now()
    supabase.table("tab_esocial").update({
        "data_grava": agora2.strftime("%Y%m%d"),
        "hora_grava": agora2.strftime("%H%M"),
    }).eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            with open(f"{_pref}_6_resultado_consulta.xml", "w", encoding="utf-8") as _f:
                _f.write(resp_cons)
        except Exception:
            pass

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar consulta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", id_reg).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1298 enviado: anomes={ano_mes} nrRec={recibo_final} cd={cd_resp}")

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "id_esocial": id_reg,
        "msg": ("eSocial ainda processando. Use Re-consultar." if aguardando
                else obs_erro or f"Enviado com sucesso. Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-1298 — API: re-consultar lote aguardando
# =========================================================
@app.route("/api/esocial_s1298_reconsultar", methods=["POST"])
def api_esocial_s1298_reconsultar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa = _get_id_empresa()
    cnpj_emp   = so_numeros(session.get("cnpj_empresa", ""))
    data       = request.get_json(force=True) or {}
    id_reg     = data.get("id_esocial")
    tpAmb      = str(data.get("tpAmb", "1"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", "1298")
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": "Registro não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    obs = (es.get("observacao_erro") or "").strip()
    if not obs.startswith("AGUARDANDO:"):
        return jsonify({"ok": False, "msg": "Registro não está em estado Aguardando."})
    protocolo = obs[len("AGUARDANDO:"):]

    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("cert_pfx_b64, cert_senha_enc")
                 .eq("cnpj", cnpj_emp).limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        emp = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": str(e)})

    pfx_bytes = base64.b64decode(emp.get("cert_pfx_b64") or "")
    senha_str = _cert_decrypt(emp.get("cert_senha_enc") or "")
    _, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])

    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""

    for tentativa in range(3):
        if tentativa:
            time.sleep(10)
        soap_cons = _soap_consultar(protocolo)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else resultado.get("descResposta", "")
        elif not recibo_final:
            obs_erro = f"Sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = (not recibo_final and not obs_erro and cd_resp in ("101", "202"))
    upd = {"recibo": recibo_final}
    if aguardando:
        upd["observacao_erro"] = f"AGUARDANDO:{protocolo}"
    elif obs_erro:
        upd["observacao_erro"] = obs_erro[:295]
    else:
        upd["observacao_erro"] = ""
    supabase.table("tab_esocial").update(upd)\
        .eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    gravar_log("ESOCIAL",
               f"S-1298 reconsulta: id={id_reg} nrRec={recibo_final} cd={cd_resp}")

    ok = bool(recibo_final) and not obs_erro and not aguardando
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "cd_resp":    cd_resp,
        "msg": ("Ainda processando." if aguardando
                else obs_erro or f"Recibo: {recibo_final}"),
    })


# =========================================================
# eSocial S-3000 — TELA
# =========================================================
@app.route("/esocial_s3000")
def esocial_s3000():
    if not session.get("logado"):
        return redirect("/")

    from collections import defaultdict

    id_empresa   = _get_id_empresa()
    anomes_atual = str(session.get("anomes_atual") or "")

    _LAYOUTS = {
        "2200": "S-2200 — Admissão",
        "2205": "S-2205 — Alt. Dados Cadastrais",
        "2206": "S-2206 — Alt. Contrato",
        "2210": "S-2210 — CAT",
        "2220": "S-2220 — Monit. Saúde",
        "2230": "S-2230 — Afastamento",
        "2299": "S-2299 — Desligamento",
    }

    def _d8(v):
        s = str(v or "").strip()
        return f"{s[6:8]}/{s[4:6]}/{s[0:4]}" if len(s) == 8 else ""

    # Registros com recibo da folha ativa (exceto layout 3000)
    elegiveis_raw = []
    if anomes_atual:
        try:
            rows = (supabase.table("tab_esocial")
                    .select("*")
                    .eq("id_empresa", id_empresa)
                    .neq("layout", "3000")
                    .eq("ano_mes", int(anomes_atual))
                    .not_.is_("recibo", "null")
                    .neq("recibo", "")
                    .execute().data or [])
            elegiveis_raw = [r for r in rows
                             if (r.get("observacao_erro") or "") != "EXCLUIDO"]
        except Exception:
            elegiveis_raw = []

    # S-3000 já enviados
    s3000_rows = []
    try:
        s3000_rows = (supabase.table("tab_esocial")
                      .select("*")
                      .eq("id_empresa", id_empresa)
                      .eq("layout", "3000")
                      .order("data_cad", desc=True)
                      .order("hora_cad", desc=True)
                      .execute().data or [])
    except Exception:
        s3000_rows = []

    mats = list({r["matricula"] for r in elegiveis_raw + s3000_rows if r.get("matricula")})
    nomes = {}
    if mats:
        try:
            for f in (supabase.table("tab_cad")
                      .select("matricula, nome")
                      .eq("id_empresa", id_empresa)
                      .in_("matricula", mats)
                      .execute().data or []):
                nomes[f["matricula"]] = f.get("nome", "")
        except Exception:
            pass

    # Agrupa elegíveis por layout
    por_layout = defaultdict(list)
    for r in elegiveis_raw:
        r["_nome"]      = nomes.get(r.get("matricula"), "—")
        r["_datagrava"] = _d8(r.get("data_grava"))
        por_layout[r["layout"]].append(r)

    layouts_disponiveis = sorted([
        {"codigo": lyt,
         "nome":   _LAYOUTS.get(lyt, f"S-{lyt}"),
         "count":  len(itens)}
        for lyt, itens in por_layout.items()
    ], key=lambda x: x["codigo"])

    for r in s3000_rows:
        recibo = (r.get("recibo") or "").strip()
        obs    = (r.get("observacao_erro") or "").strip()
        r["_nome"]      = nomes.get(r.get("matricula"), "—")
        r["_datagrava"] = _d8(r.get("data_grava"))
        if recibo:
            r["_sit"], r["_sit_label"], r["_sit_class"] = "E", "Enviado",   "sit-enviado"
        elif obs.startswith("AGUARDANDO:"):
            r["_sit"], r["_sit_label"], r["_sit_class"] = "W", "Aguardando","sit-aguardando"
        else:
            r["_sit"], r["_sit_label"], r["_sit_class"] = "X", "Com Erro",  "sit-erro"

    return render_template(
        "F10_eSocial_S3000.html",
        versao=ler_versao(),
        empresa=session.get("empresa_info", ""),
        cnpj_fmt=_fmt_cnpj(session.get("cnpj_empresa", "")),
        layouts_disponiveis=layouts_disponiveis,
        por_layout=dict(por_layout),
        s3000_rows=s3000_rows,
        anomes_atual=anomes_atual,
    )


# =========================================================
# eSocial S-3000 — API: excluir evento já enviado
# =========================================================
@app.route("/api/esocial_s3000_enviar", methods=["POST"])
def api_esocial_s3000_enviar():
    if not session.get("logado"):
        return jsonify({"ok": False, "msg": "Sessão expirada."})

    import time

    id_empresa   = _get_id_empresa()
    cnpj_emp     = so_numeros(session.get("cnpj_empresa", ""))
    anomes_atual = str(session.get("anomes_atual") or "")
    data         = request.get_json(force=True) or {}
    id_reg       = data.get("id_esocial")
    tpAmb        = str(data.get("tpAmb", "1"))
    layout       = str(data.get("layout", "2200"))

    if not id_reg:
        return jsonify({"ok": False, "msg": "id_esocial não informado."})

    # ── 1. Registro na tab_esocial ─────────────────────────
    try:
        r_es = (supabase.table("tab_esocial")
                .select("*")
                .eq("id_esocial", int(id_reg))
                .eq("id_empresa", id_empresa)
                .eq("layout", layout)
                .limit(1).execute())
        if not r_es.data:
            return jsonify({"ok": False, "msg": f"Registro S-{layout} não encontrado."})
        es = r_es.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar registro: {e}"})

    recibo_excluir = (es.get("recibo") or "").strip()
    if not recibo_excluir:
        return jsonify({"ok": False, "msg": "Este registro não possui recibo — não é possível excluir."})

    ano_mes_reg = str(es.get("ano_mes") or "")
    if anomes_atual and ano_mes_reg != anomes_atual:
        return jsonify({"ok": False,
                        "msg": f"Registro pertence ao período {ano_mes_reg}, diferente da folha ativa ({anomes_atual})."})

    matricula = es.get("matricula")

    # ── 2. CPF do funcionário ──────────────────────────────
    try:
        r_func = (supabase.table("tab_cad")
                  .select("cpf, nome")
                  .eq("id_empresa", id_empresa)
                  .eq("matricula", matricula)
                  .limit(1).execute())
        if not r_func.data:
            return jsonify({"ok": False, "msg": "Funcionário não encontrado."})
        func = r_func.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar funcionário: {e}"})

    cpf_trab = so_numeros(str(func.get("cpf") or ""))
    if len(cpf_trab) != 11:
        return jsonify({"ok": False, "msg": "CPF do funcionário inválido."})

    # ── 3. Empresa + certificado ───────────────────────────
    try:
        r_emp = (supabase.table("tab_empresa")
                 .select("*")
                 .eq("cnpj", cnpj_emp)
                 .limit(1).execute())
        if not r_emp.data:
            return jsonify({"ok": False, "msg": "Empresa não encontrada."})
        empresa = r_emp.data[0]
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao buscar empresa: {e}"})

    pfx_b64   = empresa.get("cert_pfx_b64")
    senha_enc = empresa.get("cert_senha_enc")
    if not pfx_b64 or not senha_enc:
        return jsonify({"ok": False,
                        "msg": "Certificado digital não configurado. Acesse eSocial → Certificado Digital."})

    pfx_bytes = base64.b64decode(pfx_b64)
    senha_str = _cert_decrypt(senha_enc)

    # ── 4. Gerar XML S-3000 ────────────────────────────────
    try:
        xml_str = _gerar_xml_s3000(recibo_excluir, layout, cpf_trab, empresa, tpAmb)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao gerar XML: {e}"})

    # ── 5. Diretório de diagnóstico ────────────────────────
    import os as _os2
    _now2    = datetime.now()
    _ano     = _now2.strftime("%Y")
    _ano_mes = _now2.strftime("%Y-%m")
    _emp_dir = str(id_empresa).zfill(6)
    _dir_xml = _os2.path.join(_os2.path.dirname(__file__),
                               "eSocial_XML", _ano, _ano_mes, _emp_dir)
    _os2.makedirs(_dir_xml, exist_ok=True)
    _ts   = _now2.strftime("%Y%m%d_%H%M%S")
    _pref = _os2.path.join(_dir_xml, f"S3000_{matricula}_{_ts}")

    try:
        with open(f"{_pref}_1_evento.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_str)
    except Exception:
        pass

    # ── 6. Assinar XML ─────────────────────────────────────
    try:
        xml_assinado = _assinar_xml(xml_str, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro na assinatura: {e}"})

    try:
        with open(f"{_pref}_2_assinado.xml", "w", encoding="utf-8") as _f:
            _f.write(xml_assinado)
    except Exception:
        pass

    # ── 7. Montar lote ─────────────────────────────────────
    try:
        lote_xml = _montar_lote(xml_assinado, cnpj_emp, tpAmb, pfx_bytes, senha_str)
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao montar lote: {e}"})

    try:
        with open(f"{_pref}_3_lote.xml", "w", encoding="utf-8") as _f:
            _f.write(lote_xml)
    except Exception:
        pass

    # ── 8. Enviar ao eSocial ───────────────────────────────
    url_envio, url_consulta = _ES_ENDPOINTS.get(tpAmb, _ES_ENDPOINTS["1"])
    soap_env = _soap_enviar(lote_xml)

    try:
        with open(f"{_pref}_4_soap_envio.xml", "w", encoding="utf-8") as _f:
            _f.write(soap_env)
    except Exception:
        pass

    try:
        resp_envio = _http_post_cert(url_envio, soap_env, pfx_bytes, senha_str, _SA_ENVIAR)
    except Exception as e:
        return jsonify({"ok": False, "msg": "Erro ao transmitir ao eSocial.", "detalhe": str(e)})

    try:
        with open(f"{_pref}_5_resposta.xml", "w", encoding="utf-8") as _f:
            _f.write(resp_envio)
    except Exception:
        pass

    analise         = _analisar_resposta_envio(resp_envio)
    protocolo_envio = analise["nr_rec"]
    if not protocolo_envio:
        return jsonify({"ok": False, "msg": "eSocial recusou o envio do S-3000.", "detalhe": analise["erro"]})

    # ── 9. Consultar resultado ─────────────────────────────
    recibo_final = ""
    obs_erro     = ""
    cd_resp      = ""
    dh_proc      = ""

    for tentativa in range(3):
        time.sleep(10)
        soap_cons = _soap_consultar(protocolo_envio)
        try:
            resp_cons = _http_post_cert(url_consulta, soap_cons, pfx_bytes, senha_str, _SA_CONSULTAR)
        except Exception as e:
            obs_erro = f"Erro na consulta: {e}"
            break

        try:
            with open(f"{_pref}_6_resultado_consulta.xml", "w", encoding="utf-8") as _f:
                _f.write(resp_cons)
        except Exception:
            pass

        try:
            resultado = _extrair_resultado_consulta(resp_cons)
        except Exception as e:
            obs_erro = f"Erro ao analisar resposta: {e}"
            break

        cd_resp = resultado.get("cdResposta", "")
        dh_proc = resultado.get("dhProcessamento", "") or dh_proc

        if cd_resp in ("101", "202"):
            continue

        if resultado["eventos"]:
            ev0 = resultado["eventos"][0]
            recibo_final = ev0.get("nrRec", "")
            dh_proc = ev0.get("dh", "") or dh_proc
            if ev0.get("cdResp", "") not in ("", "201"):
                ocorrs = ev0.get("ocorrs", [])
                obs_erro = " · ".join(ocorrs) if ocorrs else (
                    ev0.get("dscResp") or resultado.get("descResposta", ""))
        elif not recibo_final:
            obs_erro = f"Consulta sem recibo [{cd_resp}]: {resultado.get('descResposta','')}"
        break

    aguardando = not recibo_final and not obs_erro and cd_resp in ("101", "202")

    # ── 10. Atualizar banco ────────────────────────────────
    agora         = datetime.now()
    anomes_tp     = str(session.get("anomes_tipo") or "")
    folha_tipo_es = "1" if anomes_tp in ("1", "A") else "N"

    if recibo_final and not obs_erro and not aguardando:
        # Marca S-2200 como excluído (mantém o recibo original)
        supabase.table("tab_esocial").update({
            "observacao_erro": "EXCLUIDO",
        }).eq("id_esocial", int(id_reg)).eq("id_empresa", id_empresa).execute()

    # Grava registro S-3000
    novo_es = {
        "id_cliente":  es.get("id_cliente"),
        "id_empresa":  id_empresa,
        "data_cad":    agora.strftime("%Y%m%d"),
        "hora_cad":    agora.strftime("%H%M"),
        "id_remessa":  agora.strftime("%Y%m%d%H%M%S"),
        "ano_mes":     es.get("ano_mes"),
        "folha_tipo":  folha_tipo_es,
        "layout":      "3000",
        "matricula":   matricula,
        "data_grava":  agora.strftime("%Y%m%d"),
        "hora_grava":  agora.strftime("%H%M"),
        "codigo2":     0,
    }
    if recibo_final and not obs_erro and not aguardando:
        novo_es["recibo"] = recibo_final
    elif aguardando:
        novo_es["observacao_erro"] = f"AGUARDANDO:{protocolo_envio}"
    elif obs_erro:
        novo_es["observacao_erro"] = obs_erro[:295]
    try:
        supabase.table("tab_esocial").insert(novo_es).execute()
    except Exception:
        pass

    gravar_log("ESOCIAL",
               f"S-3000 enviado: mat={matricula} rec_excluir={recibo_excluir[:20]} nrRec={recibo_final} cd={cd_resp}",
               matricula=matricula)

    ok = bool(recibo_final) and not obs_erro and not aguardando
    _msg_ok = f"Exclusão concluída. Recibo S-3000: {recibo_final}"
    _msg_ag = "eSocial ainda está processando o S-3000. Verifique a lista em alguns instantes."
    return jsonify({
        "ok":         ok,
        "aguardando": aguardando,
        "nr_rec":     recibo_final,
        "msg":        _msg_ag if aguardando else (obs_erro or _msg_ok),
    })


