                    obs = af.get("campotxt4") or ""
                    if obs:
                        df += f"  Obs: {obs}"
                    d_atst, d_inss, _ = _split_afast_mes(di_raw_orig, df_raw, dt_ini_c, dt_fim_c, atestado_acum)
                    if d_atst is not None:
                        atestado_acum += d_atst
